import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long[] a = new long[n], b = new long[n];
        for (int k = 0; k < n; k++) a[k] = nextLong();
        for (int k = 0; k < n; k++) b[k] = nextLong();
        // Two pointers: the smaller front is the smallest value not yet output.
        StringBuilder sb = new StringBuilder();
        int i = 0, j = 0;
        while (i < n || j < n) {
            long v = j >= n || (i < n && a[i] <= b[j]) ? a[i++] : b[j++];
            if (sb.length() > 0) sb.append(' ');
            sb.append(v);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	pos := 0
	nextInt := func() int64 {
		for data[pos] <= ' ' {
			pos++
		}
		var r int64
		for pos < len(data) && data[pos] > ' ' {
			r = r*10 + int64(data[pos]-'0')
			pos++
		}
		return r
	}
	n := int(nextInt())
	a := make([]int64, n)
	b := make([]int64, n)
	for k := range a {
		a[k] = nextInt()
	}
	for k := range b {
		b[k] = nextInt()
	}
	// Two pointers: the smaller front is the smallest value not yet output.
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	i, j := 0, 0
	for i < n || j < n {
		var v int64
		if j >= n || (i < n && a[i] <= b[j]) {
			v = a[i]
			i++
		} else {
			v = b[j]
			j++
		}
		if i+j > 1 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(v, 10))
	}
	w.WriteByte('\n')
}
